class CounterEvent {}
class Increment implements CounterEvent {}
class Decrement implements CounterEvent {}
class StreamCounterBloc extends StreamBloc<CounterEvent, int> {
  StreamCounterBloc() : super(0);
  @override
  Stream<int> mapEventToStates(CounterEvent event) async* {
    if (event is Increment) yield state + 1;
    else if (event is Decrement) yield state - 1;
  }
}
